  4317  otError MleRouter::AppendChildAddresses(Message &aMessage, Child &aChild)
  4318  {
  4319      otError                   error;
  4320      Ip6::Address              address;
  4321      Child::Ip6AddressIterator iterator;
  4322      Tlv                       tlv;
  4323      AddressRegistrationEntry  entry;
  4324      Lowpan::Context           context;
  4325      uint8_t                   length      = 0;
  4326      uint16_t                  startOffset = aMessage.GetLength();
  4327
  4328      tlv.SetType(Tlv::kAddressRegistration);
  4329      SuccessOrExit(error = aMessage.Append(&tlv, sizeof(tlv)));
  4330
  4331      while (aChild.GetNextIp6Address(GetInstance(), iterator, address) == OT_ERROR_NONE)
  4332      {
  4333          if (address.IsMulticast() || Get<NetworkData::Leader>().GetContext(address, context) != OT_ERROR_NONE)
  4334          {
  4335              // uncompressed entry
  4336              entry.SetUncompressed();
  4337              entry.SetIp6Address(address);
  4338          }
  4339          else if (context.mContextId != kMeshLocalPrefixContextId)
  4340          {
  4341              // compressed entry
  4342              entry.SetContextId(context.mContextId);
  4343              entry.SetIid(address.GetIid());
  4344          }
  4345          else
  4346          {
  4347              continue;
  4348          }
  4349
  4350          SuccessOrExit(error = aMessage.Append(&entry, entry.GetLength()));
  4351          length += entry.GetLength();
  4352      }
  4353
  4354      if (length > 0)
  4355      {
  4356          tlv.SetLength(length);
  4357          aMessage.Write(startOffset, sizeof(tlv), &tlv);
  4358      }
  4359      else
  4360      {
  4361          // remove AddressRegistrationTlv if no address to be echoed back
  4362          aMessage.SetLength(startOffset);
  4363      }
  4364
  4365  exit:
